const BY_OPCODE = new Map<number, QuestOpcodeDef>(QUEST_OPCODES.map((d) => [d.opcode, d]));
const BY_NAME = new Map<string, QuestOpcodeDef>(QUEST_OPCODES.flatMap((d) => d.names.map((n) => [n, d] as const)));

export const questOpcode = (opcode: number): QuestOpcodeDef | undefined => BY_OPCODE.get(opcode);
export const questOpcodeByName = (name: string): QuestOpcodeDef | undefined => BY_NAME.get(name);
